 23	    private record Graph(int vertexCount, Edge[] edges) {
 24	        private static Graph from(int vertexCount, int[][] rawEdges) {
 25	            validateVertexCount(vertexCount);
 26	
 27	            if (rawEdges == null) {
 28	                throw new IllegalArgumentException("Edges cannot be null.");
 29	            }
 30	
 31	            Edge[] parsedEdges = new Edge[rawEdges.length];
 32	            for (int i = 0; i < rawEdges.length; i++) {
 33	                parsedEdges[i] = Edge.fromRaw(rawEdges[i], vertexCount);
 34	            }
 35	
 36	            return new Graph(vertexCount, parsedEdges);
 37	        }
 38	
 39	        private int requiredEdgeCount() {
 40	            return Math.max(0, vertexCount - 1);
 41	        }
 42	
 43	        private boolean isTriviallyConnected() {
 44	            return vertexCount <= 1;
 45	        }
 46	
 47	        private Edge[] sortedEdgesByWeight() {
 48	            Edge[] sortedEdges = edges.clone();
 49	            Arrays.sort(sortedEdges, Comparator.comparingInt(Edge::weight));
 50	            return sortedEdges;
 51	        }
 52	    }
