 66	    private record Edge(int from, int to, int weight) {
 67	        private static Edge fromRaw(int[] rawEdge, int vertexCount) {
 68	            if (rawEdge == null || rawEdge.length != EDGE_FIELD_COUNT) {
 69	                throw new IllegalArgumentException("Each edge must contain exactly 3 integers.");
 70	            }
 71	
 72	            int from = rawEdge[0];
 73	            int to = rawEdge[1];
 74	            validateVertex(from, vertexCount);
 75	            validateVertex(to, vertexCount);
 76	
 77	            return new Edge(from, to, rawEdge[2]);
 78	        }
 79	
 80	        private static void validateVertex(int vertex, int vertexCount) {
 81	            if (vertex < 0 || vertex >= vertexCount) {
 82	                throw new IllegalArgumentException(
 83	                    "Vertex index out of bounds: " + vertex
 84	                );
 85	            }
 86	        }
