 89	    private static final class KruskalSolver {
 90	        private final Graph graph;
 91	        private final DisjointSet disjointSet;
 92	
 93	        private KruskalSolver(Graph graph) {
 94	            this.graph = graph;
 95	            this.disjointSet = new DisjointSet(graph.vertexCount());
 96	        }
 97	
 98	        private MstResult compute() {
 99	            int totalWeight = 0;
100	            int edgesUsed = 0;
101	
102	            for (Edge edge : graph.sortedEdgesByWeight()) {
103	                if (!disjointSet.union(edge.from(), edge.to())) {
104	                    continue;
105	                }
106	
107	                totalWeight += edge.weight();
108	                edgesUsed++;
109	
110	                if (edgesUsed == graph.requiredEdgeCount()) {
111	                    return new MstResult(totalWeight, edgesUsed);
112	                }
113	            }
114	
115	            MstResult result = new MstResult(totalWeight, edgesUsed);
116	            if (graph.isTriviallyConnected() || result.spans(graph)) {
117	                return result;
118	            }
119	
120	            throw new IllegalArgumentException("Input graph must be connected to form an MST.");
121	        }
122	    }
123	
124	    private static final class DisjointSet {
125	        private final int[] parent;
126	        private final int[] rank;
127	
128	        private DisjointSet(int size) {
129	            parent = new int[size];
130	            rank = new int[size];
131	            for (int i = 0; i < size; i++) {
132	                parent[i] = i;
133	                rank[i] = 1;
134	            }
135	        }
136	
137	        private int find(int node) {
138	            if (parent[node] != node) {
139	                parent[node] = find(parent[node]);
140	            }
141	            return parent[node];
142	        }
143	
144	        private boolean union(int first, int second) {
145	            int firstRoot = find(first);
146	            int secondRoot = find(second);
147	
148	            if (firstRoot == secondRoot) {
149	                return false;
150	            }
151	
152	            if (rank[firstRoot] < rank[secondRoot]) {
153	                parent[firstRoot] = secondRoot;
154	            } else if (rank[firstRoot] > rank[secondRoot]) {
155	                parent[secondRoot] = firstRoot;
156	            } else {
157	                parent[secondRoot] = firstRoot;
158	                rank[firstRoot]++;
159	            }
160	
161	            return true;
162	        }
163	    }
164	}

